begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) values
 ('61000000-0000-0000-0000-000000000001','enterprise-admin@gmail.com','{}','{"nexerp_provisioned":true}'),
 ('61000000-0000-0000-0000-000000000002','enterprise-user@gmail.com','{}','{"nexerp_provisioned":true}');
update public.profiles set role = 'admin' where id = '61000000-0000-0000-0000-000000000001';
insert into public.companies(id,code,name,business_number) values ('62000000-0000-0000-0000-000000000001','EPT','Enterprise policy test','5558812345');
create temporary table draft as select jsonb_build_object('levels',(select jsonb_agg(jsonb_build_object('id',n,'name','Level '||n,'permissions','[]'::jsonb)) from generate_series(1,5) n),'members','[]'::jsonb,'mappings','[]'::jsonb,'roles','[]'::jsonb,'overrides','[]'::jsonb) policy;
grant select on draft to authenticated;
select ok(not has_table_privilege('authenticated','public.enterprise_access_policies','UPDATE'),'no direct update');
select ok(not has_table_privilege('authenticated','public.enterprise_access_policy_audit','INSERT'),'no audit forgery');
select ok(not has_function_privilege('anon','public.enterprise_save_access_policy(uuid,jsonb,integer,text)','EXECUTE'),'anonymous RPC denied');
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000001","aal":"aal1"}',true);
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',(select policy from draft),0,'test')$$,'42501','access_denied','AAL1 administrator denied');
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
select lives_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',(select policy from draft),0,'first draft')$$,'save draft');
select is((select revision from public.enterprise_access_policies where company_id='62000000-0000-0000-0000-000000000001'),1,'revision 1');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',(select policy from draft),0,'stale')$$,'40001','revision_conflict','stale rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',(select policy from draft),1,'  ')$$,'22023','invalid_policy','reason required');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001','{}',1,'bad')$$,'22023','invalid_policy','malformed JSON rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{levels,0,permissions}','[{"resource":"dashboard","action":"root","scope":"company"}]'),1,'bad')$$,'22023','invalid_policy','unknown action rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{levels,0,id}','2'),1,'bad')$$,'22023','invalid_policy','duplicate level rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{members}','[{"id":"61000000-0000-0000-0000-000000000099","name":"Missing","grade":null,"position":null,"level":null,"organizationId":null,"siteId":null,"active":true,"from":null,"to":null}]'),1,'bad')$$,'22023','invalid_policy','nonexistent profile rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{roles}','[{"id":"r","name":"Role","permissions":[],"members":["61000000-0000-0000-0000-000000000002"]}]'),1,'bad')$$,'22023','invalid_policy','role actor must be a company draft member');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{mappings}','[{"kind":"grade","code":"A","level":1,"from":null,"to":null},{"kind":"grade","code":"A","level":2,"from":null,"to":null}]'),1,'bad')$$,'22023','invalid_policy','overlapping mapping periods rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{mappings}','[{"kind":"grade","code":"A","level":1,"from":"2026-09-15","to":"2026-09-14"}]'),1,'bad')$$,'22023','invalid_policy','reversed interval rejected');
select is((select count(*)::integer from public.enterprise_access_policy_audit where company_id='62000000-0000-0000-0000-000000000001'),1,'failed saves do not audit or mutate');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{levels,0,permissions}','[{"resource":"unknown.resource","action":"read","scope":"company"}]'),1,'bad')$$,'22023','invalid_policy','unknown resource rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{mappings}','[{"kind":"grade","code":"A","level":1,"from":"now","to":null}]'),1,'bad')$$,'22023','invalid_policy','relative date rejected');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',jsonb_set((select policy from draft),'{mappings}','[{"kind":"grade","code":"A","level":1,"from":"infinity","to":null}]'),1,'bad')$$,'22023','invalid_policy','infinite date rejected');
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000002","aal":"aal2"}',true);
select set_config('request.jwt.claim.sub','61000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from public.enterprise_access_policies),0,'ordinary user cannot read drafts');
select is((select count(*)::integer from public.enterprise_access_policy_audit),0,'ordinary user cannot read audit');
select throws_ok($$select public.enterprise_save_access_policy('62000000-0000-0000-0000-000000000001',(select policy from draft),1,'forbidden')$$,'42501','access_denied','ordinary user cannot write');
select * from finish();
rollback;
